{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "A close N-benzylpiperidine-containing radiotracer achieved 3.4% injected dose per gram in brain in vivo, demonstrating that this scaffold readily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The N-benzylpiperidine analogue [18F]3 showed a brain-to-blood ratio rising from 2.2 to 6.3 in mice, confirming sustained CNS entry.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Planar imaging in monkeys showed significant brain accumulation of an N-benzylpiperidine benzamide, directly supporting CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A 1-benzyl-4-piperidinyl benzamide exhibited significant and lasting high brain uptake in mice, supporting the brain-penetrant nature of the shared piperidine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "ON013100, a lipophilic phenolic/methoxy compound, achieved a brain/plasma ratio of 0.92 in mice, supporting that phenolic/methoxy analogues can have high CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer analogues containing the same N-benzylpiperidine and phenolic/methoxy motifs show robust brain uptake in rodents, monkeys, and humans; the consistent experimental evidence outweighs the moderate physicochemical prior.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule; evidence is from close analogues.",
    "Efflux transporter status was not directly measured for the query, but consistent in vivo uptake across analogues mitigates this concern.",
    "The low neutral fraction at pH 7.4 may reduce passive permeability, but transporter-mediated and/or active uptake appears sufficient based on analogue data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

